<script>
class XDetails extends HTMLElement {
  constructor() {
    super();
    // Attach a Shadow DOM tree
    this.attachShadow({ mode: 'open' });
    this.expanded = false;               // start collapsed

    /* ---------- Styles (inside the shadow tree) ---------- */
    const style = document.createElement('style');
    style.textContent = `
      :host {
        display: block;
        font-family: Arial, Helvetica, sans-serif;
      }

      /* Header area – square button + header text */
      .header-area {
        display: flex;
        align-items: center;
        margin-bottom: 4px;
        border-bottom: 1px solid #bbb;   /* bottom border */
        padding-bottom: 2px;
        font-size: 1.1em;                /* slightly larger font */
      }

      .toggle {
        width: 1em;
        height: 1em;
        margin-right: 0.5em;
        cursor: pointer;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        border: none;
        background: transparent;
      }
      .toggle.plus  { color: #2e7d32; }   /* plus when expanded */
      .toggle.minus { color: #c62828; }   /* minus when collapsed */

      /* Intro part – always visible while collapsed */
      .intro-area {
        margin-bottom: 4px;
      }

      /* Expand‑more button – shown only when collapsed */
      .expand-btn {
        padding: 4px 8px;
        cursor: pointer;
        border: 1px solid #888;
        background: #f5f5f5;
      }

      /* Details part – shown only when expanded */
      .details-area {
        margin-top: 4px;
      }
    `;
    this.shadowRoot.appendChild(style);

    /* ---------- Build the shadow tree ---------- */

    // 1️⃣ Header toggle button (+ / -)
    const toggleBtn = document.createElement('button');
    toggleBtn.className = 'toggle plus';
    toggleBtn.setAttribute('aria-label', 'Expand details');

    // 2️⃣ Header slot
    const headerSlot = document.createElement('slot');
    headerSlot.name = 'header';

    // 3️⃣ Intro area (projected slot) + “expand more” button
    const introArea = document.createElement('div');
    introArea.className = 'intro-area';
    const introSlot = document.createElement('slot');
    introSlot.name = 'intro';
    const expandBtn = document.createElement('button');
    expandBtn.className = 'expand-btn';
    expandBtn.textContent = 'expand more';
    expandBtn.style.display = 'block';   // visible while collapsed

    // 4️⃣ Details area (projected slot)
    const detailsArea = document.createElement('div');
    detailsArea.className = 'details-area';
    const detailsSlot = document.createElement('slot');
    detailsSlot.name = 'details';

    // Assemble everything
    this.shadowRoot.append(
      toggleBtn,
      headerSlot,
      introArea,
      introSlot,
      expandBtn,
      detailsArea,
      detailsSlot
    );

    /* ---------- Event handling ---------- */
    toggleBtn.addEventListener('click', () => this._toggle());
    expandBtn.addEventListener('click', () => this._toggle());
  }

  /** Toggle between collapsed / expanded states */
  _toggle() {
    if (this.expanded) {
      // ---- Collapse ----
      this.expanded = false;
      toggleBtn.classList.remove('plus');
      toggleBtn.classList.add('minus');
      expandBtn.style.display = 'block';
      introArea.style.display = 'none';
      detailsArea.style.display = 'none';
    } else {
      // ---- Expand ----
      this.expanded = true;
      toggleBtn.classList.remove('minus');
      toggleBtn.classList.add('plus');
      expandBtn.style.display = 'none';
      introArea.style.display = 'block';
      detailsArea.style.display = 'block';
    }
  }
}

// Register the custom element
customElements.define('x-details', XDetails);
</script>
```

